window.__finlexDocLoaded(10213,{"id":10213,"articles":[{"id":1000883,"no":"Overview","heading":"Scope & Core Objective (Public Summary)","text":"Covers stockholders' equity transactions including treasury stock (cost vs. par value method), stock dividends and stock splits, spin-offs, and reverse spin-offs.","seq":0},{"id":1000884,"no":"ASC 505-10 / 505-30","heading":"Treasury Stock, Stock Dividends & Spin-Offs","text":"• Treasury Stock (ASC 505-30): Accounted for under the cost method or par value method; no gain or loss is ever recognized in net income on treasury stock transactions.\n• Small vs. Large Stock Dividends (ASC 505-20): Stock dividends < 20%–25% capitalize retained earnings at FAIR VALUE; large stock dividends (> 20%–25%, stock splits effected in the form of a dividend) capitalize at PAR VALUE.","seq":1},{"id":1000885,"no":"US GAAP vs. IFRS / CAS","heading":"Key Cross-Framework Differences","text":"• Largely aligned with IAS 32 on treasury shares (no P&L recognition), while US GAAP preserves specific small vs. large stock dividend capitalization conventions.","seq":2},{"id":1000886,"no":"Official Access","heading":"Official FASB Codification & Reference Entry","text":"Official Portal (FASB Accounting Standards Codification®): https://asc.fasb.org/\nStatus: in_force (FASB ASC free Basic View available at https://asc.fasb.org/).","seq":3}]});
